export const RUNTIME_SCHEMA_THEMES: string[] = Object.keys(runtimeSchemas).sort()

/**
 * Block schemas for a theme, as the renderer needs them.
 * Unknown theme returns an empty map rather than throwing — a missing schema
 * degrades to "no defaults", which is recoverable; a throw blanks the page.
 */
export function getRuntimeBlockSchemas(theme: string): Record<string, RuntimeBlockSchema> {
  return runtimeSchemas[theme] ?? {}
}
